#include <stdio.h>
#include <string.h>
#include <ctype.h>

int soundex_digit(char c) {
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    const char *input = argv[1];
    if (input[0] == '\0') {
        puts("EMPTY");
        return 0;
    }
    char code[5]; // 4 chars + null terminator
    // first letter, uppercase
    code[0] = (char)toupper((unsigned char)input[0]);
    int prev_digit = soundex_digit(code[0]);
    int count = 1; // number of characters filled in code
    for (size_t i = 1; input[i] != '\0' && count < 4; ++i) {
        char ch = input[i];
        if (!isalpha((unsigned char)ch))
            continue; // skip non‑letters
        char up = (char)toupper((unsigned char)ch);
        if (up == 'H' || up == 'W')
            continue; // ignored characters
        int digit = soundex_digit(up);
        if (digit == 0)
            continue; // vowels and other non‑coded letters
        if (digit == prev_digit)
            continue; // duplicate code
        code[count++] = (char)('0' + digit);
        prev_digit = digit;
    }
    while (count < 4) {
        code[count++] = '0';
    }
    code[4] = '\0';
    puts(code);
    return 0;
}
